param([Parameter(Mandatory=$true)][string]$OutputPath,[Parameter(Mandatory=$true)][string]$TaskSpecPath)
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Split-Path -Parent $PSScriptRoot));$output=[IO.Path]::GetFullPath($OutputPath);$spec=[IO.Path]::GetFullPath($TaskSpecPath);$base=Join-Path $root 'scripts/build_full_scope_semantic_promote_v35.ps1';$adapter=Join-Path $root 'scripts/tdimarc_native_generation_exception_rescue_v23.lsp'
foreach($path in @($output,$spec,$base,$adapter)){if(-not$path.StartsWith($root+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){throw 'SPV36_PATH_OUTSIDE_PROJECT'}}
$result=&$base -OutputPath $output -TaskSpecPath $spec;if([string]$result.status-cne'PASS'){throw 'SPV36_BASE'}
$text=[IO.File]::ReadAllText($output,[Text.Encoding]::UTF8);$autorunNeedle='(c:CXTDIMARCFULLBATCH)';$autorun=$text.LastIndexOf($autorunNeedle,[StringComparison]::Ordinal);if($autorun-lt0){throw 'SPV36_AUTORUN'};$adapterText=[IO.File]::ReadAllText($adapter,[Text.Encoding]::UTF8).Trim();$text=$text.Insert($autorun,$adapterText+[Environment]::NewLine+[Environment]::NewLine);[IO.File]::WriteAllText($output,$text,[Text.UTF8Encoding]::new($false))
$start=$text.LastIndexOf('(defun cx:er22-direct-source-fraction-rescue',[StringComparison]::Ordinal);$end=$text.LastIndexOf($autorunNeedle,[StringComparison]::Ordinal);if($start-lt0-or$end-le$start){throw 'SPV36_ACTIVE_REGION'};$active=$text.Substring($start,$end-$start)
foreach($token in @('cx:sp2-staged-tdimarc','0.35 0.65 0.20 0.80 0.50','EXCEPTION_DIRECT_SOURCE_STAGED_FRACTION_V23','cx:pg-audit-normal-p','cx:fb-delete-handles')){if(-not$active.Contains($token,[StringComparison]::Ordinal)){throw ('SPV36_REQUIRED:'+$token)}}
foreach($forbidden in @('cx:ss-v2-run-one','vl-catch-all-apply ''command','8D/ARC/8','87/ARC/2','404333','287195','vla-Save','TMirDim')){if($active.Contains($forbidden,[StringComparison]::OrdinalIgnoreCase)){throw ('SPV36_FORBIDDEN:'+$forbidden)}}
if([regex]::IsMatch($text,'(?im)^[ \t]*\(prin(?:[ \t]|\()')){throw 'SPV36_TRUNCATED_PRINC'};if(([regex]::Matches($text,'(?m)^\(c:CXTDIMARCFULLBATCH\)[ \t]*\r?$')).Count-ne1){throw 'SPV36_AUTORUN_COUNT'}
$lex=&(Join-Path $root 'scripts/assert_autolisp_lexical_balance_v1.ps1') -LispPath $output;if([string]$lex.status-cne'PASS'-or[int]$lex.final_depth-ne0){throw 'SPV36_LEXICAL'}
[pscustomobject]@{status='PASS';output=$output;sha256=(Get-FileHash -LiteralPath $output -Algorithm SHA256).Hash;task_count=[int]$result.task_count;ordinary_policy='RANK2_BYTE_PRESERVED';exception_policy='ORDINARY_BELOW2__DIRECT_SOURCE_STAGED_ADAPTIVE_FRACTIONS__TRANSLATED_FULL_POLYLINE__RANK2_ONLY';commanded_grip4_count=0;board_specific_algorithm_literals=0;truncated_prin_tokens=0;autorun_count=1;direct_command_context='FIELD_PROVEN_STAGED_TDIMARC'}
